import { useCallback, useState } from 'react';
import {
  JxBadge,
  JxDivider,
  JxSelect,
  JxSlider,
  JxSwitch,
  JxToggle,
} from '@jinx-ui/react';

export type AppearanceTheme = 'system' | 'light' | 'dark';

export interface AppearanceSettings {
  theme: AppearanceTheme;
  scale: number;
  dense: boolean;
  fontFamily: string;
}

export interface AppearanceSettingsScreenProps {
  defaultValue?: Partial<AppearanceSettings>;
  onChange?: (value: AppearanceSettings) => void;
}

const THEME_ITEMS: { value: AppearanceTheme; label: string }[] = [
  { value: 'system', label: 'Системная' },
  { value: 'light', label: 'Светлая' },
  { value: 'dark', label: 'Тёмная' },
];

const FONT_OPTIONS = [
  { value: 'sans', label: 'Inter Tight', meta: 'Без засечек' },
  { value: 'display', label: 'Fraunces', meta: 'С засечками' },
  { value: 'mono', label: 'JetBrains Mono', meta: 'Моноширинный' },
];

export default function AppearanceSettingsScreen({
  defaultValue,
  onChange,
}: AppearanceSettingsScreenProps) {
  const [settings, setSettings] = useState<AppearanceSettings>({
    theme: defaultValue?.theme ?? 'system',
    scale: defaultValue?.scale ?? 100,
    dense: defaultValue?.dense ?? false,
    fontFamily: defaultValue?.fontFamily ?? 'sans',
  });

  const update = useCallback(
    (patch: Partial<AppearanceSettings>) => {
      setSettings((prev) => {
        const next = { ...prev, ...patch };
        onChange?.(next);
        return next;
      });
    },
    [onChange],
  );

  const themeLabel =
    THEME_ITEMS.find((item) => item.value === settings.theme)?.label ?? '';

  return (
    <section
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '20px',
        padding: '24px',
        maxWidth: '520px',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
      }}
    >
      <header
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: '12px',
          flexWrap: 'wrap',
        }}
      >
        <h2
          style={{
            margin: 0,
            fontFamily: 'var(--jx-font-display)',
            fontSize: '20px',
            color: 'var(--jx-text)',
          }}
        >
          Внешний вид
        </h2>
        <JxBadge tone="accent" dot>
          {themeLabel}
        </JxBadge>
      </header>

      <JxToggle
        items={THEME_ITEMS}
        value={settings.theme}
        onValueChange={(value) => update({ theme: value as AppearanceTheme })}
      />

      <JxSlider
        label="Масштаб интерфейса"
        min={80}
        max={140}
        step={10}
        unit="%"
        showOutput
        value={settings.scale}
        onValueChange={(value) => update({ scale: value })}
      />

      <JxSwitch
        label="Плотная вёрстка"
        checked={settings.dense}
        onChange={(event) => update({ dense: event.target.checked })}
      />

      <JxDivider label="Ещё" />

      <JxSelect
        label="Шрифт интерфейса"
        placeholder="Выберите шрифт"
        options={FONT_OPTIONS}
        value={settings.fontFamily}
        onValueChange={(value) => update({ fontFamily: value })}
      />
    </section>
  );
}

